import { DashboardShell } from "@/shared/components/dashboard-shell";
import { setServiceProviderVerified } from "@backend/admin/actions";
import { getAdminData } from "@backend/admin/queries";
import { requireRole } from "@backend/auth/session";
import { BadgeCheck, Store } from "lucide-react";
export const dynamic = "force-dynamic";
export default async function AdminVendorsPage() { const session = await requireRole("admin"); const { vendors } = await getAdminData(); return <DashboardShell role="admin" name={session.fullName} active="Vendor trust"><p className="eyebrow text-berry">Marketplace quality</p><h1 className="display mt-2 text-4xl font-semibold">Vendor trust.</h1><section className="mt-8 max-w-4xl rounded-[22px] border border-ink/10 bg-white p-5 sm:p-7">{vendors.length ? vendors.map((vendor) => <article key={vendor.id} className="flex items-center justify-between gap-4 py-4 first:pt-0"><div className="flex items-center gap-3"><img src={vendor.imageUrl} alt="" className="size-11 rounded-full object-cover"/><div><p className="font-bold">{vendor.businessName}</p><p className="mt-1 text-xs text-ink/48">{vendor.city} · {vendor.completedEvents} events</p></div></div><form action={setServiceProviderVerified}><input type="hidden" name="vendorId" value={vendor.id}/><input type="hidden" name="verified" value={vendor.verified ? "false" : "true"}/><button className={vendor.verified ? "btn-primary !min-h-9 !px-3 text-xs" : "btn-secondary !min-h-9 !px-3 text-xs"}><BadgeCheck size={14}/>{vendor.verified ? "Verified" : "Verify"}</button></form></article>) : <div className="py-12 text-center"><Store className="mx-auto text-ink/25"/><p className="mt-4 text-sm text-ink/50">No service providers yet.</p></div>}</section></DashboardShell>; }
